const body = $json.body ?? $json;

return [{
  json: {
    source: body.source || 'api',
    userId: body.userId || undefined,
    channelId: body.channelId || undefined,
    rawRequest: body.rawRequest || '',
    requester: body.requester || 'unknown',
    normalizedType: body.normalizedType || 'general_request',
    targetSystem: body.targetSystem || 'unknown-system',
    requestedEntitlement: body.requestedEntitlement || undefined,
    businessReason: body.businessReason || undefined,
    clarificationNeeded: Boolean(body.clarificationNeeded),
    missingFields: Array.isArray(body.missingFields) ? body.missingFields : [],
    candidateWorkflows: Array.isArray(body.candidateWorkflows) ? body.candidateWorkflows : [],
    initialTrustMode: body.initialTrustMode || 'human_approved_execution'
  }
}];
